// One event loop, watching every socket via OS readiness notification
const reactor = createEventLoop();

function registerHandler(socket: Socket, handler: (data: Buffer) => void) {
  reactor.watch(socket, "readable", () => {
    const data = socket.readNonBlocking();
    handler(data); // dispatched only when data is actually ready
  });
}

server.on("connection", (socket) => {
  registerHandler(socket, (data) => handle(data));
});

reactor.run(); // single thread services every registered socket
